/* INTDIS ($EF54) - FORCE WATCHDOG RESET
 * Condition codes out: NZVC.
 */
void intdis(void)
{
l_intdis:;
    CK(0xEF54);
    CYC(3);
    goto l_intdis;                                   /* LEF54  ANYTHING OTHER THAN IRQ OR RESET HANGS IN */
}

