    CYC(3);
    A = hw_rd8(R_BYT0);                              /* LEF8E */
    CYC(13);
    JSR(debnce);                                     /* LEF91 */
    A = hw_rd8(R_BYT1);                              /* LEF94 */
    CYC(13);
    JSR(debnce);                                     /* LEF97 */
