    CYC(13);
    JSR(debnce);                                     /* LEF9D */
    A = hw_rd8(R_BYT3);                              /* LEFA0 */
    CYC(13);
    JSR(debnce);                                     /* LEFA3 */
    A = M8(VG_LSN);                                  /* LEFA6  PREVIOUS NEW VALUE */
    M8(VG_LSO) = A;                                  /* LEFA8  IS CURRENT OLD VALUE */
