    B = (uint8_t)(B + 0x02);                         /* LF0A2 */
    CYC(11);
    if (B >= (VTLZSZ-VTLZS)) {                       /* LF0A6  IFHS   */
        B = 0;                                       /* LF0A8 */
        CYC(2);
    }
    M8(VG_LZS) = B;                                  /* LF0A9 */
    U = VTLZS;                                       /* LF0AB */
    D = rd16((uint16_t)(U + (int8_t)B));             /* LF0AE */
